import { useState } from 'react';
import { motion } from 'framer-motion';
import clsx from 'clsx';
import './AcidRadioGroup.css';

export interface AcidRadioOption {
    value: string;
    label: string;
    description?: string;
    disabled?: boolean;
}

export interface AcidRadioGroupProps {
    options: AcidRadioOption[];
    value?: string;
    defaultValue?: string;
    onChange?: (value: string) => void;
    label?: string;
    orientation?: 'vertical' | 'horizontal';
    className?: string;
}

export const AcidRadioGroup = ({
    options,
    value,
    defaultValue,
    onChange,
    label,
    orientation = 'vertical',
    className
}: AcidRadioGroupProps) => {
    const [internalValue, setInternalValue] = useState(defaultValue || '');
    const selected = value !== undefined ? value : internalValue;

    const handleSelect = (val: string) => {
        setInternalValue(val);
        onChange?.(val);
    };

    return (
        <div className={clsx('ac-radio-group', className)}>
            {label && <span className="ac-radio-group-label">{label}</span>}
            <div className={clsx('ac-radio-group-list', `ac-radio-group-${orientation}`)}>
                {options.map((opt) => (
                    <label
                        key={opt.value}
                        className={clsx('ac-radio-item', opt.disabled && 'ac-radio-disabled', selected === opt.value && 'ac-radio-selected')}
                        onClick={() => !opt.disabled && handleSelect(opt.value)}
                    >
                        <div className={clsx('ac-radio-indicator', selected === opt.value && 'ac-radio-indicator-checked')}>
                            <motion.div
                                className="ac-radio-dot"
                                initial={false}
                                animate={{
                                    scale: selected === opt.value ? 1 : 0,
                                    opacity: selected === opt.value ? 1 : 0
                                }}
                                transition={{ type: 'spring', stiffness: 500, damping: 30 }}
                            />
                        </div>
                        <div className="ac-radio-text">
                            <span className="ac-radio-label">{opt.label}</span>
                            {opt.description && <span className="ac-radio-description">{opt.description}</span>}
                        </div>
                    </label>
                ))}
            </div>
        </div>
    );
};

.ac-radio-group {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.ac-radio-group-label {
    font-family: var(--font-mono);
    font-size: 0.75rem;
    letter-spacing: 0.1em;
    color: var(--ac-text-muted);
    text-transform: uppercase;
}

.ac-radio-group-list {
    display: flex;
    gap: 0.5rem;
}

.ac-radio-group-vertical {
    flex-direction: column;
}

.ac-radio-group-horizontal {
    flex-direction: row;
    flex-wrap: wrap;
}

.ac-radio-item {
    display: flex;
    align-items: flex-start;
    gap: 0.75rem;
    padding: 0.75rem 1rem;
    border: 1px solid var(--ac-border-muted);
    cursor: pointer;
    transition: all 0.2s ease;
    position: relative;
}

.ac-radio-item:hover {
    border-color: var(--ac-border-bright);
    background: var(--ac-surface-hover);
}

.ac-radio-selected {
    border-color: var(--ac-brand) !important;
    background: color-mix(in srgb, var(--ac-brand) 5%, transparent);
}

.ac-radio-disabled {
    opacity: 0.4;
    cursor: not-allowed;
    pointer-events: none;
}

.ac-radio-indicator {
    width: 18px;
    height: 18px;
    border: 1px solid var(--ac-border-bright);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    margin-top: 2px;
    transition: border-color 0.2s;
    background: transparent;
}

.ac-radio-indicator-checked {
    border-color: var(--ac-brand);
}

.ac-radio-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: var(--ac-brand);
}

.ac-radio-text {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

.ac-radio-label {
    font-family: var(--font-mono);
    font-size: 0.875rem;
    color: var(--ac-text-primary);
    font-weight: 500;
}

.ac-radio-description {
    font-size: 0.8rem;
    color: var(--ac-text-muted);
    font-family: var(--font-mono);
}
